// Unit 0 homework: lines review, linear inequalities, absolute value and
// piecewise functions. Most problems are generated by src/lines.js (exact
// fractions, graphs drawn from the equation); `check`/`exp` hold the answer
// key so scripts/verify.mjs and scripts/verify_sympy.py can confirm it.
import { absProblem, absWrite, graphLine, ineqFromGraph, line, pwGraphProblem, pwEvalProblem, pwPlane, pwGraphSteps, pwWriteProblem, slopeProblem, vline, writeLine } from '../../lines.js'

const R = String.raw
const rad = (prompt, expr, result, steps, answer) => ({ type: 'steps', prompt, steps, answer, check: { expr, result, positive: true } })
const val = (prompt, value, result, steps, answer) => ({ type: 'steps', prompt, steps, answer, check: { value, result } })
const same = (prompt, expr, result, steps, answer) => ({ type: 'steps', prompt, steps, answer, check: { expr, result } })
const roots = (prompt, expr, rts, steps, answer, variable = 'x') => ({ type: 'steps', prompt, steps, answer, check: { expr, roots: rts, variable } })
const hand = (prompt, steps, answer, extra = {}) => ({ type: 'steps', prompt, steps, answer, ...extra })
const absTex = (a, h, k) => {
  const c = a === 1 ? '' : a === -1 ? '-' : Array.isArray(a) ? `${a[0] < 0 ? '-' : ''}\\tfrac{${Math.abs(a[0])}}{${a[1]}}` : a
  const inner = h === 0 ? 'x' : `x ${h < 0 ? '+' : '-'} ${Math.abs(h)}`
  return `${c}|${inner}|${k === 0 ? '' : k < 0 ? ` - ${-k}` : ` + ${k}`}`
}
const abs = (a, h, k, ask, exp, prompt) => ({ ...absProblem(prompt ?? R`y = ${absTex(a, h, k)}`, a, h, k, ask), exp })
const withStep = (p, step) => ({ ...p, steps: [...p.steps, step] })
// piece shorthands
const ln = (m, b, lo, hi, loIn = false, hiIn = false) => ({ m, b, lo, hi, loIn, hiIn })
const cst = (c, lo, hi, loIn = false, hiIn = false) => ({ c, lo, hi, loIn, hiIn })
const av = (a, h, k, lo, hi, loIn = false, hiIn = false) => ({ abs: [a, h, k], lo, hi, loIn, hiIn })
// line keys (sympy, = 0)
const si = (m, b) => `y - (${m}*x + ${b})`
const std = (A, B, C) => `${A}*x + ${B}*y - (${C})`
const vk = c => `x - (${c})`

// HW #5 Part I: the six lettered graphs, matched by their endpoint dots.
const MATCH = [
  [[ln(1, -4, null, 1, false, true), ln(3, 0, 1, null)], 'E'],
  [[ln(1, 4, null, 0), ln(2, 3, 0, null, true)], 'F'],
  [[ln(1, 4, null, 0, false, true), ln(2, 4, 0, null)], 'B'],
  [[cst(-5, null, -1), ln(3, -1, -1, null, true)], 'C'],
  [[ln(3, -2, null, 1, false, true), ln(1, 2, 1, null)], 'D'],
  [[ln(-3, -1, null, 1, false, true), cst(-5, 1, null)], 'A'],
]
const MATCH_PROMPTS = [
  R`1.\ f(x) = \begin{cases} x - 4, & x \le 1 \\ 3x, & x > 1 \end{cases}`,
  R`2.\ f(x) = \begin{cases} 2x + 3, & x \ge 0 \\ x + 4, & x < 0 \end{cases}`,
  R`3.\ f(x) = \begin{cases} x + 4, & x \le 0 \\ 2x + 4, & x > 0 \end{cases}`,
  R`4.\ f(x) = \begin{cases} 3x - 1, & x \ge -1 \\ -5, & x < -1 \end{cases}`,
  R`5.\ f(x) = \begin{cases} 3x - 2, & x \le 1 \\ x + 2, & x > 1 \end{cases}`,
  R`6.\ f(x) = \begin{cases} -3x - 1, & x \le 1 \\ -5, & x > 1 \end{cases}`,
]
const match = ([pieces, letter], i) => ({
  type: 'steps', prompt: MATCH_PROMPTS[i],
  steps: [...pwGraphSteps(pieces), R`The only graph with those dots is **graph ${letter}**.`],
  answer: R`\text{Graph ${letter}}`, plane: pwPlane(pieces, [-6, 6, -8, 8]),
})

